#pragma once

// GENERATED from engine/rust/crates/ffi/src/keys.rs (the FFI_KEY_* and
// FFI_NAMED_KEY_* constants) and engine/rust/crates/platform/src/input/key.rs
// (the variant names). The numbers are part of the ABI; src/Keys.cpp checks
// every one of them against ffi.h with static_assert, so a drift fails the
// build. Do not edit by hand: add a key to the Rust enum, to keys.rs and
// regenerate.

#include <cstdint>
