/// The name of a key ("KeyW", "ArrowLeft", ...), for logs and key bindings.
/// "Unknown" for a value outside the enum.
[[nodiscard]] std::string_view KeyName(KeyCode key) noexcept;

/// The name of a named key ("Enter", "F5", ...), "Unknown" for a value outside
/// the enum.
